let appLanguage='ar';
try{appLanguage=localStorage.getItem('coach-language')==='en'?'en':'ar';}catch{}
function appLocale(){return appLanguage==='en'?'en-GB':'ar-KW';}
const translationPattern=new RegExp('(?<![\\u0621-\\u065f\\u066e-\\u06d3\\u06fa-\\u06ff])('+Object.keys(englishText).sort((a,b)=>b.length-a.length).map(s=>s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|')+')(?![\\u0621-\\u065f\\u066e-\\u06d3\\u06fa-\\u06ff])','g');
function tr(text){return appLanguage==='en'?String(text??'').replace(translationPattern,key=>englishText[key]).replace(/(\d+) من (\d+) selected/g,'$1 of $2 selected').replace(/؛/g,'; ').replace(/،/g,','):String(text??'');}
function languageSettings(){return `<div class="card" style="margin-bottom:16px"><h3>اللغة</h3><div class="field"><label for="appLanguage">لغة التطبيق</label><select id="appLanguage" onchange="setAppLanguage(this.value)"><option value="ar" ${appLanguage==='ar'?'selected':''}>العربية</option><option value="en" ${appLanguage==='en'?'selected':''}>English</option></select></div><p class="hint">تُحفظ اللغة على هذا الجهاز. تبقى بياناتك وصورك كما هي.</p></div>`;}
function setAppLanguage(value){
 if(!['ar','en'].includes(value))return;
 appLanguage=value;
 try{localStorage.setItem('coach-language',value);}catch{}
 nav();render();
}
// Translate visible copy only. Never rewrite user input, record keys, option values or handlers.
const originalCopy=new WeakMap();let languageObserver;
function localizedValue(node,key,value){
 const entries=originalCopy.get(node)||{};let item=entries[key];
 if(!item||value!==item.translated)item={original:value,translated:value};
 item.translated=tr(item.original);entries[key]=item;originalCopy.set(node,entries);return item.translated;
}
function localizeUI(){
 if(!document.createTreeWalker||!document.body)return;
 languageObserver?.disconnect();
 try{
  document.documentElement.lang=appLanguage;document.documentElement.dir=appLanguage==='en'?'ltr':'rtl';
  document.title=appLanguage==='en'?'AZM | Strength & Nutrition':'عزم | قوة وتغذية';
  // Explicit values preserve Arabic activity/group keys when option labels become English.
  for(const option of document.querySelectorAll('option'))if(!option.hasAttribute('value'))option.setAttribute('value',option.textContent);
  const walker=document.createTreeWalker(document.body,4);let node;
  while(node=walker.nextNode()){
   if(node.parentElement?.closest('script,style,textarea,[data-no-translate]'))continue;
   const value=localizedValue(node,'text',node.nodeValue);if(value!==node.nodeValue)node.nodeValue=value;
  }
  for(const element of document.querySelectorAll('[placeholder],[alt],[title],[aria-label]')){
   for(const key of ['placeholder','alt','title','aria-label'])if(element.hasAttribute(key)){
    const value=localizedValue(element,key,element.getAttribute(key));if(value!==element.getAttribute(key))element.setAttribute(key,value);
   }
  }
 }finally{languageObserver?.observe(document.body,{subtree:true,childList:true,characterData:true});}
}
if(typeof window!=='undefined'){
 if(typeof window.alert==='function'){const nativeAlert=window.alert.bind(window);window.alert=message=>nativeAlert(tr(message));}
 if(typeof window.confirm==='function'){const nativeConfirm=window.confirm.bind(window);window.confirm=message=>nativeConfirm(tr(message));}
 if(typeof MutationObserver!=='undefined'){
  languageObserver=new MutationObserver(localizeUI);
  if(document.body)localizeUI();else document.addEventListener('DOMContentLoaded',localizeUI,{once:true});
 }
}
